/** Side by side (editor | output) from this width on; stacked below it (phones). */
private val WIDE_LAYOUT = 840.dp

/**
 * The playground: the menu bar, one row of controls (wrapping on narrow screens), then the DIMACS
 * editor and the output.
 */
@Composable
fun PlaygroundScreen(vm: PlaygroundViewModel) {
    var showExamples by remember { mutableStateOf(false) }
    var showOptions by remember { mutableStateOf(false) }
    var showAbout by remember { mutableStateOf(false) }
    var help by remember { mutableStateOf<HelpPage?>(null) }
    val loadFile = rememberFileLoader(onLoaded = vm::loadDimacs, onFailed = vm::logError)
    // the text being saved: the save finishes later (a file dialog), and only that text is then saved
    var savingText by remember { mutableStateOf("") }
    val saveToFile = rememberFileSaver(onSaved = { vm.fileSaved(it, savingText) }, onFailed = vm::logError)
    fun save() {
        savingText = vm.dimacs
        saveToFile(SAVE_FILE_NAME, savingText)
    }
    vm.pendingAction?.let {
        AlertDialog(
            onDismissRequest = vm::cancelPending,
            text = { Text("A computation is still running. Stop it to continue?") },
            confirmButton = { TextButton(onClick = vm::confirmPending) { Text("Stop computation") } },
            dismissButton = { TextButton(onClick = vm::cancelPending) { Text("Keep running") } },
        )
    }

    Column(Modifier.fillMaxSize()) {
        PlaygroundMenuBar(
            vm,
            onExamples = { vm.whenStopped { showExamples = true } },
            onLoadFile = { vm.whenStopped { vm.leave(loadFile) } },
            onSave = ::save,
            onOptions = { vm.whenStopped { showOptions = true } },
            onHelp = { help = it },
            onAbout = { showAbout = true },
        )
        Column(Modifier.weight(1f).padding(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
            Controls(vm)
            BoxWithConstraints(Modifier.weight(1f).fillMaxWidth()) {
                if (maxWidth >= WIDE_LAYOUT) {
                    // a draggable divider between the two (ported from ktoy)
                    SplitPane(
                        listOf(
                            SplitPanel("editor") { Editor(vm, it.fillMaxSize()) },
                            SplitPanel("output") { Output(vm, it.fillMaxSize()) },
                        ),
                        vm.splitWeights,
                        { vm.splitWeights = it },
                        horizontal = true,
                        modifier = Modifier.fillMaxSize(),
                    )
                } else {
                    Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                        Editor(vm, Modifier.weight(1f).fillMaxWidth())
                        Output(vm, Modifier.weight(1f).fillMaxWidth())
                    }
                }
            }
        }
    }

    if (showExamples) ExamplesDialog(vm, onClose = { showExamples = false })
    if (showOptions) OptionsDialog(vm, onClose = { showOptions = false })
    help?.let { HelpDialog(it) { help = null } }
    if (showAbout) AboutDialog(onLinkFailed = vm::logError, onClose = { showAbout = false })
    // last, so it sits on top of the Examples dialog that asked for it
    if (vm.pendingLeave != null) {
        UnsavedEditsDialog(onSave = ::save, onDiscard = vm::discardAndLeave, onCancel = vm::cancelLeave)
    }
}

/** The suggested name for CNF → Save…. */
private const val SAVE_FILE_NAME = "formula.cnf"

/** "Save changes?" before Load file or an example replaces a CNF with unsaved edits (as in ksat-chess). */
@Composable
private fun UnsavedEditsDialog(onSave: () -> Unit, onDiscard: () -> Unit, onCancel: () -> Unit) {
    AlertDialog(
        onDismissRequest = onCancel,
        title = { Text("Save changes?") },
        text = { Text("The CNF has changes that are not saved to a file yet.") },
        confirmButton = { TextButton(onClick = onSave) { Text("Save…") } },
        dismissButton = {
            Row {
                TextButton(onClick = onDiscard) { Text("Discard") }
                TextButton(onClick = onCancel) { Text("Cancel") }
            }
        },
    )
}

@Composable
private fun Controls(vm: PlaygroundViewModel) {
    ControlRow {
        for (mode in Mode.entries) {
            Row(
                Modifier.selectable(selected = vm.mode == mode, onClick = { vm.whenStopped { vm.chooseMode(mode) } }, role = Role.RadioButton),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                RadioButton(selected = vm.mode == mode, onClick = null)
                Text(mode.label, Modifier.padding(start = 4.dp, end = 8.dp))
            }
        }
        // one button: Solve, which becomes Stop while a computation runs
        Button(onClick = { if (vm.running) vm.stop() else vm.solve() }, Modifier.width(96.dp)) {
            Text(if (vm.running) "Stop" else "Solve")
        }
        OutlinedButton(onClick = { vm.showSolutions = !vm.showSolutions }) {
            Text(if (vm.showSolutions) "Hide solutions" else "Show solutions")
        }
    }
}

/** One row of controls; wraps on narrow screens. */
@Composable
private fun ControlRow(content: @Composable () -> Unit) {
    FlowRow(
        horizontalArrangement = Arrangement.spacedBy(8.dp),
        verticalArrangement = Arrangement.spacedBy(4.dp),
        itemVerticalAlignment = Alignment.CenterVertically,
    ) { content() }
}

/** The DIMACS editor: grows with its text inside a scrolling box with a scrollbar. */
@Composable
private fun Editor(vm: PlaygroundViewModel, modifier: Modifier) {
    val vScroll = rememberScrollState()
    BoxWithConstraints(modifier) {
        val minHeight = maxHeight
        ScrollbarBox(vScroll, Modifier.fillMaxSize()) {
            OutlinedTextField(
                value = vm.dimacs,
                onValueChange = { text -> vm.whenStopped { vm.dimacs = text } },
                modifier = Modifier.verticalScroll(vScroll).fillMaxWidth().heightIn(min = minHeight)
                    .padding(end = 8.dp).testTag("editor"),
                label = { Text("DIMACS CNF") },
                textStyle = LocalMonoStyle.current,
            )
        }
    }
}

/** The output of the latest run: one time-stamped line per event, solutions shown on the toggle. */
@Composable
private fun Output(vm: PlaygroundViewModel, modifier: Modifier) {
    val listState = rememberLazyListState()
    LaunchedEffect(vm.log.size) {
        if (vm.log.isNotEmpty()) listState.scrollToItem(vm.log.size - 1)
    }
    val mono = LocalMonoStyle.current.copy(color = OUTPUT_TEXT)
    // top padding: line up with the editor's outline, which sits below its floating label
    Column(modifier.padding(top = 8.dp).background(OUTPUT_BACKGROUND, RoundedCornerShape(4.dp)).padding(8.dp)) {
        Text("Output", style = mono.copy(color = OUTPUT_DIM))
        Spacer(Modifier.height(4.dp))
        ScrollbarBox(listState, Modifier.fillMaxSize(), thumbColor = OUTPUT_THUMB) {
            LazyColumn(Modifier.fillMaxSize().padding(end = 8.dp).testTag("output"), state = listState) {
                items(vm.log) { line ->
                    // time stamp and message side by side, so a wrapped message stays indented
                    Row(Modifier.fillMaxWidth()) {
                        Text(formatTimestamp(line.timeMillis) + "  ", style = mono.copy(color = OUTPUT_DIM))
                        Column(Modifier.weight(1f)) {
                            Text(line.text, style = mono)
                            val solution = line.solution
                            if (solution != null && vm.showSolutions) {
                                Text(formatSolution(solution), style = mono.copy(color = OUTPUT_SOLUTION))
                            }
                        }
                    }
                }
            }
        }
    }
}

private val OUTPUT_BACKGROUND = Color(0xFF1E1E1E)
private val OUTPUT_TEXT = Color(0xFFD4D4D4)
private val OUTPUT_DIM = Color(0xFF8A8A8A)
private val OUTPUT_SOLUTION = Color(0xFF9CDCFE)
private val OUTPUT_THUMB = Color(0x66FFFFFF)

/**
 * One radio button per [Example]; the selected one shows its parameter fields and description.
 * Generate creates the instance into the editor (in the background; Cancel stops it).
 */
@Composable
private fun ExamplesDialog(vm: PlaygroundViewModel, onClose: () -> Unit) {
    val selected = vm.selectedExample
    val texts = vm.selectedTexts
    fun cancel() {
        vm.cancelGeneration()
        onClose()
    }
    BigDialog(
        "Examples",
        onDismiss = ::cancel,
        buttons = {
            TextButton(onClick = ::cancel) { Text("Cancel") }
            // replaces the CNF: asks first if it has unsaved edits
            TextButton(
                onClick = { vm.leave { vm.generate(selected, texts, onFinished = onClose) } },
                enabled = !vm.generating && texts.all(::isParamText),
            ) { Text("Generate") }
        },
    ) {
        val vScroll = rememberScrollState()
        ScrollbarBox(vScroll, Modifier.weight(1f).fillMaxWidth()) {
            Column(Modifier.verticalScroll(vScroll).padding(end = 12.dp), verticalArrangement = Arrangement.spacedBy(4.dp)) {
                for (example in Example.entries) {
                    Row(
                        Modifier.fillMaxWidth()
                            .selectable(selected = example == selected, onClick = { vm.selectedExample = example }, role = Role.RadioButton),
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        RadioButton(selected = example == selected, onClick = null)
                        Text(example.title, Modifier.padding(start = 8.dp))
                    }
                    if (example == selected) {
                        Column(Modifier.padding(start = 40.dp, bottom = 8.dp), verticalArrangement = Arrangement.spacedBy(4.dp)) {
                            val chosen = vm.examplePresets.getValue(example)
                            for (row in example.presets) {
                                FlowRow {
                                    for (p in row) SmallRadio(p.label, chosen.value == p, Modifier.width(140.dp)) { chosen.value = p }
                                }
                            }
                            if (example.presets.isNotEmpty()) SmallRadio("custom", chosen.value == null) { chosen.value = null }
                            if (chosen.value == null) for ((param, value) in example.params.zip(vm.exampleTexts.getValue(example))) {
                                Row(verticalAlignment = Alignment.CenterVertically) {
                                    Text("${param.name} (${param.meaning}):", Modifier.padding(end = 4.dp))
                                    // any non-negative Int: at most 10 digits
                                    NumberField(
                                        value = value.value,
                                        onValueChange = { value.value = it },
                                        chars = Int.MAX_VALUE.toString().length,
                                        tag = "param-${param.name}",
                                        isError = !isParamText(value.value),
                                        enabled = !vm.generating,
                                        steps = 0..Int.MAX_VALUE,
                                    )
                                }
                            }
                            val ints = texts.mapNotNull { if (isParamText(it)) it.trim().toIntOrNull() else null }
                            if (ints.size == texts.size) {
                                Text("expected behavior: ${example.expected(ints)}", style = MaterialTheme.typography.bodySmall)
                            }
                            if (example.description.isNotEmpty()) {
                                Text(example.description, style = MaterialTheme.typography.bodySmall)
                            }
                        }
                    }
                }
                if (vm.generating) Text("generating ...")
            }
        }
    }
}

/** A radio button with [label], for the presets of an example. */
@Composable
private fun SmallRadio(label: String, selected: Boolean, modifier: Modifier = Modifier, onClick: () -> Unit) {
    Row(
        modifier.selectable(selected = selected, onClick = onClick, role = Role.RadioButton),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        RadioButton(selected = selected, onClick = null)
        Text(label, Modifier.padding(start = 4.dp, end = 4.dp))
    }
}

/**
 * All options of the selected solver ([solverOptions]): name, upstream description and default;
 * a checkbox for BOOL, a text field for INT / DOUBLE. Edits take effect at once and are kept per
 * solver for the session; only values that differ from the default are passed to the solver.
 */
@Composable
private fun OptionsDialog(vm: PlaygroundViewModel, onClose: () -> Unit) {
    val solver = vm.solver
    val options = remember(solver) { solverOptions(solver) }
    BigDialog(
        "${solver.name} options",
        onDismiss = onClose,
        buttons = {
            if (options.isNotEmpty()) TextButton(onClick = { vm.resetOptions(solver) }) { Text("Reset to defaults") }
            TextButton(onClick = onClose) { Text("Close") }
        },
    ) {
        if (options.isEmpty()) {
            Text("${solver.name} has no options.")
        } else {
            val listState = rememberLazyListState()
            ScrollbarBox(listState, Modifier.weight(1f).fillMaxWidth()) {
                LazyColumn(Modifier.padding(end = 12.dp), state = listState, verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    items(options, key = { it.name }) { option -> OptionRow(vm, solver, option) }
                }
            }
        }
    }
}

@Composable
private fun OptionRow(vm: PlaygroundViewModel, solver: Solver, option: SolverOption) {
    val text = vm.optionText(solver, option)
    Column {
        Row(verticalAlignment = Alignment.CenterVertically) {
            Text(option.name, Modifier.weight(1f), style = LocalMonoStyle.current, fontWeight = FontWeight.Bold)
            if (option.type == OptionType.BOOL) {
                Checkbox(
                    checked = parseOptionValue(text)?.toDouble() == 1.0,
                    onCheckedChange = { vm.setOptionText(solver, option.name, if (it) "1" else "0") },
                )
            } else {
                NumberField(
                    value = text,
                    onValueChange = { vm.setOptionText(solver, option.name, it) },
                    chars = optionChars(option),
                    tag = "option-${option.name}",
                    isError = parseOptionValue(text) == null,
                )
            }
        }
        Text(
            "${option.help} (default: ${formatOptionValue(option.default)})",
            style = MaterialTheme.typography.bodySmall,
        )
    }
}

/**
 * Width of an option's field in characters: an INT option's longest bound (e.g. 10 digits up to
 * Int.MAX_VALUE, a sign for negative bounds); a DOUBLE option 10 characters (a decimal like 0.999
 * or 91648253.0; its bounds can be huge).
 */
internal fun optionChars(option: SolverOption): Int =
    if (option.type == OptionType.INT) maxOf(formatOptionValue(option.min).length, formatOptionValue(option.max).length)
    else 10

/** About: build identity, the two repos, license texts (as in ksat-chess). Modeled on ktoy's About. */
@Composable
private fun AboutDialog(onLinkFailed: (String) -> Unit, onClose: () -> Unit) {
    BigDialog("ksat playground", onDismiss = onClose, buttons = { TextButton(onClick = onClose) { Text("OK") } }) {
        val vScroll = rememberScrollState()
        ScrollbarBox(vScroll, Modifier.weight(1f).fillMaxWidth()) {
            Column(Modifier.verticalScroll(vScroll).padding(end = 12.dp).testTag("about")) {
                Text("Kotlin Multiplatform ports of state-of-the-art SAT solvers (MiniSat, CaDiCaL, kissat, MicroSAT). Runs on JVM, Android, iOS, native and in the browser.")
                Spacer(Modifier.height(8.dp))
                FeedbackBox("ksat is in early development. Feedback is very welcome:", onLinkFailed)
                Spacer(Modifier.height(8.dp))
                ProjectLine("ksat", "https://github.com/manfredscheucher/ksat", "the solver ports", onLinkFailed)
                ProjectLine("ksat-extra", "https://github.com/manfredscheucher/ksat-extra", "this playground, benchmarks and website", onLinkFailed)
                Text("The original solvers are MIT-licensed too.", Modifier.padding(vertical = 2.dp))
                if (isWeb) {
                    // collapsed by default, like the license texts
                    var showTerms by remember { mutableStateOf(false) }
                    TextButton(onClick = { showTerms = !showTerms }) {
                        Text(if (showTerms) "Hide terms & privacy" else "Terms & privacy")
                    }
                    if (showTerms) {
                        Text("Privacy", style = MaterialTheme.typography.labelLarge, modifier = Modifier.padding(top = 4.dp))
                        for (p in WEB_PRIVACY) Text(p, style = MaterialTheme.typography.bodySmall, modifier = Modifier.padding(top = 4.dp))
                        Text("Terms", style = MaterialTheme.typography.labelLarge, modifier = Modifier.padding(top = 8.dp))
                        for (p in WEB_TERMS) Text(p, style = MaterialTheme.typography.bodySmall, modifier = Modifier.padding(top = 4.dp))
                    }
                }
                Spacer(Modifier.height(8.dp))
                val build = buildList {
                    val sha = GeneratedBuildInfo.COMMIT_SHA
                    if (sha != "unknown") add(if (GeneratedBuildInfo.IS_DIRTY == "dirty") "$sha (modified)" else sha)
                    if (GeneratedBuildInfo.COMMIT_DATE != "unknown") add("committed ${GeneratedBuildInfo.COMMIT_DATE}")
                    add("built ${GeneratedBuildInfo.BUILD_DATE}")
                }
                Text(
                    build.joinToString(" · "),
                    style = MaterialTheme.typography.bodySmall,
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                )
                var showLicenses by remember { mutableStateOf(false) }
                TextButton(onClick = { showLicenses = !showLicenses }) {
                    Text(if (showLicenses) "Hide license texts" else "License texts")
                }
                if (showLicenses) {
                    for (notice in GeneratedLicenses.NOTICES) {
                        HorizontalDivider(Modifier.padding(vertical = 8.dp))
                        Text(notice.title, style = MaterialTheme.typography.titleSmall, color = MaterialTheme.colorScheme.primary)
                        Text(notice.text, style = MaterialTheme.typography.bodySmall)
                    }
                }
            }
        }
    }
}

